# Expected values are SymPy's outputs for the same calls (categories diagram drawing).

for (s in c("A","B","C","D","E","F","G","H")) assign(s, Object(s))
f <- NamedMorphism(A, B, "f"); g <- NamedMorphism(B, C, "g"); h <- NamedMorphism(C, D, "h"); i <- NamedMorphism(D, E, "i")
k <- NamedMorphism(D, B, "k"); l <- NamedMorphism(A, C, "l"); m <- NamedMorphism(C, A, "m"); n <- NamedMorphism(B, D, "n")
f1 <- NamedMorphism(B, A, "f1"); g1 <- NamedMorphism(C, B, "g1"); loopA <- NamedMorphism(A, A, "lA"); loopB <- NamedMorphism(B, B, "lB")
d1 <- NamedMorphism(A, D, "d1"); e1 <- NamedMorphism(E, F, "e1")
p1 <- NamedMorphism(A, B, "p1"); p2 <- NamedMorphism(A, C, "p2"); p3 <- NamedMorphism(B, D, "p3"); p4 <- NamedMorphism(C, D, "p4")
p5 <- NamedMorphism(A, E, "p5"); p6 <- NamedMorphism(B, F, "p6"); p7 <- NamedMorphism(C, G, "p7"); p8 <- NamedMorphism(D, H, "p8")
p9 <- NamedMorphism(E, F, "p9"); p10 <- NamedMorphism(E, G, "p10"); p11 <- NamedMorphism(F, H, "p11"); p12 <- NamedMorphism(G, H, "p12")

dg <- function(d, mode) switch(mode, grid = format(DiagramGrid(d)), seq = format(DiagramGrid(d, layout = "sequential")),
  tr = format(DiagramGrid(d, transpose = TRUE)), xy = xypic_draw_diagram(d), xyseq = xypic_draw_diagram(d, layout = "sequential"))
nl <- function(s) gsub("\n", "\\n", s, fixed = TRUE)

test_that("diagram layouts and Xy-pic output match SymPy", {
  expect_equal(nl(dg(Diagram(list(f)), "grid")), "[[Object(\"A\"), Object(\"B\")]]")
  expect_equal(nl(dg(Diagram(list(f)), "seq")), "[[Object(\"A\"), Object(\"B\")]]")
  expect_equal(nl(dg(Diagram(list(f)), "tr")), "[[Object(\"A\")], [Object(\"B\")]]")
  expect_equal(nl(dg(Diagram(list(f)), "xy")), "\\xymatrix{\\nA \\ar[r]^{f} & B \\n}\\n")
  expect_equal(nl(dg(Diagram(list(f)), "xyseq")), "\\xymatrix{\\nA \\ar[r]^{f} & B \\n}\\n")
  expect_equal(nl(dg(Diagram(list(f, g)), "grid")), "[[Object(\"A\"), Object(\"B\")], [None, Object(\"C\")]]")
  expect_equal(nl(dg(Diagram(list(f, g)), "seq")), "[[Object(\"A\"), Object(\"B\"), Object(\"C\")]]")
  expect_equal(nl(dg(Diagram(list(f, g)), "tr")), "[[Object(\"A\"), None], [Object(\"B\"), Object(\"C\")]]")
  expect_equal(nl(dg(Diagram(list(f, g)), "xy")), "\\xymatrix{\\nA \\ar[r]^{f} & B \\ar[d]^{g} \\\\\\n& C \\n}\\n")
  expect_equal(nl(dg(Diagram(list(f, g)), "xyseq")), "\\xymatrix{\\nA \\ar[r]^{f} & B \\ar[r]^{g} & C \\n}\\n")
  expect_equal(nl(dg(Diagram(list(f, g, h)), "grid")), "[[Object(\"A\"), Object(\"B\"), None], [None, Object(\"C\"), Object(\"D\")]]")
  expect_equal(nl(dg(Diagram(list(f, g, h)), "seq")), "[[Object(\"A\"), Object(\"B\"), Object(\"C\"), Object(\"D\")]]")
  expect_equal(nl(dg(Diagram(list(f, g, h)), "tr")), "[[Object(\"A\"), None], [Object(\"B\"), Object(\"C\")], [None, Object(\"D\")]]")
  expect_equal(nl(dg(Diagram(list(f, g, h)), "xy")), "\\xymatrix{\\nA \\ar[r]^{f} & B \\ar[d]^{g} & \\\\\\n& C \\ar[r]_{h} & D \\n}\\n")
  expect_equal(nl(dg(Diagram(list(f, g, h)), "xyseq")), "\\xymatrix{\\nA \\ar[r]^{f} & B \\ar[r]^{g} & C \\ar[r]^{h} & D \\n}\\n")
  expect_equal(nl(dg(Diagram(list(f, g, h, i)), "grid")), "[[Object(\"A\"), Object(\"B\"), None], [None, Object(\"C\"), Object(\"D\")], [None, None, Object(\"E\")]]")
  expect_equal(nl(dg(Diagram(list(f, g, h, i)), "seq")), "[[Object(\"A\"), Object(\"B\"), Object(\"C\"), Object(\"D\"), Object(\"E\")]]")
  expect_equal(nl(dg(Diagram(list(f, g, h, i)), "tr")), "[[Object(\"A\"), None, None], [Object(\"B\"), Object(\"C\"), None], [None, Object(\"D\"), Object(\"E\")]]")
  expect_equal(nl(dg(Diagram(list(f, g, h, i)), "xy")), "\\xymatrix{\\nA \\ar[r]^{f} & B \\ar[d]^{g} & \\\\\\n& C \\ar[r]^{h} & D \\ar[d]^{i} \\\\\\n& & E \\n}\\n")
  expect_equal(nl(dg(Diagram(list(f, g, h, i)), "xyseq")), "\\xymatrix{\\nA \\ar[r]^{f} & B \\ar[r]^{g} & C \\ar[r]^{h} & D \\ar[r]^{i} & E \\n}\\n")
  expect_equal(nl(dg(Diagram(list(f, g), list(g * f)), "grid")), "[[Object(\"A\"), Object(\"B\")], [None, Object(\"C\")]]")
  expect_equal(nl(dg(Diagram(list(f, g), list(g * f)), "seq")), "[[Object(\"A\"), Object(\"B\"), Object(\"C\")]]")
  expect_equal(nl(dg(Diagram(list(f, g), list(g * f)), "tr")), "[[Object(\"A\"), None], [Object(\"B\"), Object(\"C\")]]")
  expect_equal(nl(dg(Diagram(list(f, g), list(g * f)), "xy")), "\\xymatrix{\\nA \\ar[r]^{f} & B \\ar[d]^{g} \\\\\\n& C \\n}\\n")
  expect_equal(nl(dg(Diagram(list(f, g), list(g * f)), "xyseq")), "\\xymatrix{\\nA \\ar[r]^{f} & B \\ar[r]^{g} & C \\n}\\n")
  expect_equal(nl(dg(Diagram(list(f, g, h, k)), "grid")), "[[Object(\"A\"), Object(\"B\")], [Object(\"D\"), Object(\"C\")]]")
  expect_equal(nl(dg(Diagram(list(f, g, h, k)), "seq")), "[[Object(\"A\"), Object(\"B\"), Object(\"C\"), Object(\"D\")]]")
  expect_equal(nl(dg(Diagram(list(f, g, h, k)), "tr")), "[[Object(\"A\"), Object(\"D\")], [Object(\"B\"), Object(\"C\")]]")
  expect_equal(nl(dg(Diagram(list(f, g, h, k)), "xy")), "\\xymatrix{\\nA \\ar[r]^{f} & B \\ar[d]^{g} \\\\\\nD \\ar[ru]^{k} & C \\ar[l]^{h} \\n}\\n")
  expect_equal(nl(dg(Diagram(list(f, g, h, k)), "xyseq")), "\\xymatrix{\\nA \\ar[r]^{f} & B \\ar[r]^{g} & C \\ar[r]^{h} & D \\ar@/^3mm/[ll]^{k} \\n}\\n")
  expect_equal(nl(dg(Diagram(list(f, g, l)), "grid")), "[[Object(\"A\"), Object(\"B\")], [Object(\"C\"), None]]")
  expect_equal(nl(dg(Diagram(list(f, g, l)), "seq")), "[[Object(\"A\"), Object(\"B\"), Object(\"C\")]]")
  expect_equal(nl(dg(Diagram(list(f, g, l)), "tr")), "[[Object(\"A\"), Object(\"C\")], [Object(\"B\"), None]]")
  expect_equal(nl(dg(Diagram(list(f, g, l)), "xy")), "\\xymatrix{\\nA \\ar[r]^{f} \\ar[d]_{l} & B \\ar[ld]^{g} \\\\\\nC & \\n}\\n")
  expect_equal(nl(dg(Diagram(list(f, g, l)), "xyseq")), "\\xymatrix{\\nA \\ar[r]^{f} \\ar@/_3mm/[rr]_{l} & B \\ar[r]^{g} & C \\n}\\n")
  expect_equal(nl(dg(Diagram(list(f, g, h, n)), "grid")), "[[Object(\"A\"), Object(\"B\")], [Object(\"D\"), Object(\"C\")]]")
  expect_equal(nl(dg(Diagram(list(f, g, h, n)), "seq")), "[[Object(\"A\"), Object(\"B\"), Object(\"C\"), Object(\"D\")]]")
  expect_equal(nl(dg(Diagram(list(f, g, h, n)), "tr")), "[[Object(\"A\"), Object(\"D\")], [Object(\"B\"), Object(\"C\")]]")
  expect_equal(nl(dg(Diagram(list(f, g, h, n)), "xy")), "\\xymatrix{\\nA \\ar[r]^{f} & B \\ar[d]^{g} \\ar[ld]^{n} \\\\\\nD & C \\ar[l]^{h} \\n}\\n")
  expect_equal(nl(dg(Diagram(list(f, g, h, n)), "xyseq")), "\\xymatrix{\\nA \\ar[r]^{f} & B \\ar[r]^{g} \\ar@/_3mm/[rr]_{n} & C \\ar[r]^{h} & D \\n}\\n")
  expect_equal(nl(dg(Diagram(list(f, f1, g, g1)), "grid")), "[[Object(\"A\"), Object(\"B\")], [None, Object(\"C\")]]")
  expect_equal(nl(dg(Diagram(list(f, f1, g, g1)), "seq")), "[[Object(\"A\"), Object(\"B\"), Object(\"C\")]]")
  expect_equal(nl(dg(Diagram(list(f, f1, g, g1)), "tr")), "[[Object(\"A\"), None], [Object(\"B\"), Object(\"C\")]]")
  expect_equal(nl(dg(Diagram(list(f, f1, g, g1)), "xy")), "\\xymatrix{\\nA \\ar[r]^{f} & B \\ar@/^3mm/[l]^{f_{1}} \\ar[d]^{g} \\\\\\n& C \\ar@/^3mm/[u]^{g_{1}} \\n}\\n")
  expect_equal(nl(dg(Diagram(list(f, f1, g, g1)), "xyseq")), "\\xymatrix{\\nA \\ar[r]^{f} & B \\ar@/^3mm/[l]^{f_{1}} \\ar[r]^{g} & C \\ar@/^3mm/[l]^{g_{1}} \\n}\\n")
  expect_equal(nl(dg(Diagram(list(f, g, loopA, loopB)), "grid")), "[[Object(\"A\"), Object(\"B\")], [None, Object(\"C\")]]")
  expect_equal(nl(dg(Diagram(list(f, g, loopA, loopB)), "seq")), "[[Object(\"A\"), Object(\"B\"), Object(\"C\")]]")
  expect_equal(nl(dg(Diagram(list(f, g, loopA, loopB)), "tr")), "[[Object(\"A\"), None], [Object(\"B\"), Object(\"C\")]]")
  expect_equal(nl(dg(Diagram(list(f, g, loopA, loopB)), "xy")), "\\xymatrix{\\nA \\ar[r]^{f} \\ar@(u,l)[]^{lA} & B \\ar[d]^{g} \\ar@(r,u)[]^{lB} \\\\\\n& C \\n}\\n")
  expect_equal(nl(dg(Diagram(list(f, g, loopA, loopB)), "xyseq")), "\\xymatrix{\\nA \\ar[r]^{f} \\ar@(u,l)[]^{lA} & B \\ar[r]^{g} \\ar@(r,u)[]^{lB} & C \\n}\\n")
  expect_equal(nl(dg(Diagram(list(f, g, m)), "grid")), "[[Object(\"A\"), Object(\"B\")], [Object(\"C\"), None]]")
  expect_equal(nl(dg(Diagram(list(f, g, m)), "seq")), "[[Object(\"A\"), Object(\"B\"), Object(\"C\")]]")
  expect_equal(nl(dg(Diagram(list(f, g, m)), "tr")), "[[Object(\"A\"), Object(\"C\")], [Object(\"B\"), None]]")
  expect_equal(nl(dg(Diagram(list(f, g, m)), "xy")), "\\xymatrix{\\nA \\ar[r]^{f} & B \\ar[ld]^{g} \\\\\\nC \\ar[u]^{m} & \\n}\\n")
  expect_equal(nl(dg(Diagram(list(f, g, m)), "xyseq")), "\\xymatrix{\\nA \\ar[r]^{f} & B \\ar[r]^{g} & C \\ar@/^3mm/[ll]^{m} \\n}\\n")
  expect_equal(nl(dg(Diagram(list(f, d1, g, h)), "grid")), "[[Object(\"A\"), Object(\"B\")], [Object(\"D\"), Object(\"C\")]]")
  expect_equal(nl(dg(Diagram(list(f, d1, g, h)), "seq")), "[[Object(\"A\"), Object(\"B\"), Object(\"C\"), Object(\"D\")]]")
  expect_equal(nl(dg(Diagram(list(f, d1, g, h)), "tr")), "[[Object(\"A\"), Object(\"D\")], [Object(\"B\"), Object(\"C\")]]")
  expect_equal(nl(dg(Diagram(list(f, d1, g, h)), "xy")), "\\xymatrix{\\nA \\ar[r]^{f} \\ar[d]_{d_{1}} & B \\ar[d]^{g} \\\\\\nD & C \\ar[l]^{h} \\n}\\n")
  expect_equal(nl(dg(Diagram(list(f, d1, g, h)), "xyseq")), "\\xymatrix{\\nA \\ar[r]^{f} \\ar@/_3mm/[rrr]_{d_{1}} & B \\ar[r]^{g} & C \\ar[r]^{h} & D \\n}\\n")
  expect_equal(nl(dg(Diagram(list(f, e1)), "grid")), "[[Object(\"A\"), Object(\"B\"), Object(\"E\"), Object(\"F\")]]")
  expect_equal(nl(dg(Diagram(list(f, e1)), "seq")), "[[Object(\"A\"), Object(\"B\"), Object(\"E\"), Object(\"F\")]]")
  expect_equal(nl(dg(Diagram(list(f, e1)), "tr")), "[[Object(\"A\"), Object(\"B\")], [Object(\"E\"), Object(\"F\")]]")
  expect_equal(nl(dg(Diagram(list(f, e1)), "xy")), "\\xymatrix{\\nA \\ar[r]^{f} & B & E \\ar[r]^{e_{1}} & F \\n}\\n")
  expect_equal(nl(dg(Diagram(list(f, e1)), "xyseq")), "\\xymatrix{\\nA \\ar[r]^{f} & B & E \\ar[r]^{e_{1}} & F \\n}\\n")
  expect_equal(nl(dg(Diagram(list(f, g, e1)), "grid")), "[[Object(\"E\"), Object(\"F\"), Object(\"A\"), Object(\"B\")], [None, None, None, Object(\"C\")]]")
  expect_equal(nl(dg(Diagram(list(f, g, e1)), "seq")), "[[Object(\"E\"), Object(\"F\"), Object(\"A\"), Object(\"B\"), Object(\"C\")]]")
  expect_equal(nl(dg(Diagram(list(f, g, e1)), "tr")), "[[Object(\"E\"), Object(\"F\")], [Object(\"A\"), Object(\"B\")], [None, Object(\"C\")]]")
  expect_equal(nl(dg(Diagram(list(f, g, e1)), "xy")), "\\xymatrix{\\nE \\ar[r]^{e_{1}} & F & A \\ar[r]^{f} & B \\ar[d]^{g} \\\\\\n& & & C \\n}\\n")
  expect_equal(nl(dg(Diagram(list(f, g, e1)), "xyseq")), "\\xymatrix{\\nE \\ar[r]^{e_{1}} & F & A \\ar[r]^{f} & B \\ar[r]^{g} & C \\n}\\n")
  expect_equal(nl(dg(Diagram(list(p1, p2, p3, p4, p5, p6, p7, p8, p9, p10, p11, p12)), "grid")), "[[None, Object(\"E\"), Object(\"F\"), None], [None, Object(\"A\"), Object(\"B\"), None], [Object(\"G\"), Object(\"C\"), Object(\"D\"), Object(\"H\")]]")
  expect_equal(nl(dg(Diagram(list(p1, p2, p3, p4, p5, p6, p7, p8, p9, p10, p11, p12)), "seq")), "[[Object(\"A\"), Object(\"B\"), Object(\"D\"), Object(\"C\"), Object(\"G\"), Object(\"E\"), Object(\"F\"), Object(\"H\")]]")
  expect_equal(nl(dg(Diagram(list(p1, p2, p3, p4, p5, p6, p7, p8, p9, p10, p11, p12)), "tr")), "[[None, None, Object(\"G\")], [Object(\"E\"), Object(\"A\"), Object(\"C\")], [Object(\"F\"), Object(\"B\"), Object(\"D\")], [None, None, Object(\"H\")]]")
  expect_equal(nl(dg(Diagram(list(p1, p2, p3, p4, p5, p6, p7, p8, p9, p10, p11, p12)), "xy")), "\\xymatrix{\\n& E \\ar[r]^{p_{9}} \\ar[ldd]_{p_{10}} & F \\ar[rdd]^{p_{11}} & \\\\\\n& A \\ar[r]^{p_{1}} \\ar[d]^{p_{2}} \\ar[u]^{p_{5}} & B \\ar[d]^{p_{3}} \\ar[u]_{p_{6}} & \\\\\\nG \\ar@/_3mm/[rrr]_{p_{12}} & C \\ar[r]^{p_{4}} \\ar[l]_{p_{7}} & D \\ar[r]^{p_{8}} & H \\n}\\n")
  expect_equal(nl(dg(Diagram(list(p1, p2, p3, p4, p5, p6, p7, p8, p9, p10, p11, p12)), "xyseq")), "\\xymatrix{\\nA \\ar[r]^{p_{1}} \\ar@/_3mm/[rrr]_{p_{2}} \\ar@/_3mm/[rrrrr]_{p_{5}} & B \\ar[r]^{p_{3}} \\ar@/_3mm/[rrrrr]_{p_{6}} & D \\ar@/_3mm/[rrrrr]_{p_{8}} & C \\ar[l]_{p_{4}} \\ar[r]^{p_{7}} & G \\ar@/_3mm/[rrr]_{p_{12}} & E \\ar[r]^{p_{9}} \\ar[l]_{p_{10}} & F \\ar[r]^{p_{11}} & H \\n}\\n")
  expect_equal(nl(dg(Diagram(list(f, g, h, i, NamedMorphism(E, A, "j"))), "grid")), "[[None, Object(\"A\"), Object(\"B\")], [Object(\"D\"), Object(\"E\"), Object(\"C\")]]")
  expect_equal(nl(dg(Diagram(list(f, g, h, i, NamedMorphism(E, A, "j"))), "seq")), "[[Object(\"A\"), Object(\"B\"), Object(\"C\"), Object(\"D\"), Object(\"E\")]]")
  expect_equal(nl(dg(Diagram(list(f, g, h, i, NamedMorphism(E, A, "j"))), "tr")), "[[None, Object(\"D\")], [Object(\"A\"), Object(\"E\")], [Object(\"B\"), Object(\"C\")]]")
  expect_equal(nl(dg(Diagram(list(f, g, h, i, NamedMorphism(E, A, "j"))), "xy")), "\\xymatrix{\\n& A \\ar[r]^{f} & B \\ar[d]^{g} \\\\\\nD \\ar[r]^{i} & E \\ar[u]^{j} & C \\ar@/^3mm/[ll]^{h} \\n}\\n")
  expect_equal(nl(dg(Diagram(list(f, g, h, i, NamedMorphism(E, A, "j"))), "xyseq")), "\\xymatrix{\\nA \\ar[r]^{f} & B \\ar[r]^{g} & C \\ar[r]^{h} & D \\ar[r]^{i} & E \\ar@/^3mm/[llll]^{j} \\n}\\n")
  expect_equal(nl(dg(Diagram(list(f, g, h, NamedMorphism(D, A, "q"), NamedMorphism(A, C, "r"))), "grid")), "[[Object(\"A\"), Object(\"B\")], [Object(\"D\"), Object(\"C\")]]")
  expect_equal(nl(dg(Diagram(list(f, g, h, NamedMorphism(D, A, "q"), NamedMorphism(A, C, "r"))), "seq")), "[[Object(\"B\"), Object(\"A\"), Object(\"C\"), Object(\"D\")]]")
  expect_equal(nl(dg(Diagram(list(f, g, h, NamedMorphism(D, A, "q"), NamedMorphism(A, C, "r"))), "tr")), "[[Object(\"A\"), Object(\"D\")], [Object(\"B\"), Object(\"C\")]]")
  expect_equal(nl(dg(Diagram(list(f, g, h, NamedMorphism(D, A, "q"), NamedMorphism(A, C, "r"))), "xy")), "\\xymatrix{\\nA \\ar[r]^{f} \\ar[rd]^{r} & B \\ar[d]^{g} \\\\\\nD \\ar[u]^{q} & C \\ar[l]^{h} \\n}\\n")
  expect_equal(nl(dg(Diagram(list(f, g, h, NamedMorphism(D, A, "q"), NamedMorphism(A, C, "r"))), "xyseq")), "\\xymatrix{\\nB \\ar@/_3mm/[rr]_{g} & A \\ar[l]_{f} \\ar[r]^{r} & C \\ar[r]^{h} & D \\ar@/^3mm/[ll]^{q} \\n}\\n")
  expect_equal(nl(dg(Diagram(list(list(f, "unique"), list(g, list())), list(list(g * f, "unique"))), "grid")), "[[Object(\"A\"), Object(\"B\")], [Object(\"C\"), None]]")
  expect_equal(nl(dg(Diagram(list(list(f, "unique"), list(g, list())), list(list(g * f, "unique"))), "seq")), "[[Object(\"A\"), Object(\"B\"), Object(\"C\")]]")
  expect_equal(nl(dg(Diagram(list(list(f, "unique"), list(g, list())), list(list(g * f, "unique"))), "tr")), "[[Object(\"A\"), Object(\"C\")], [Object(\"B\"), None]]")
  expect_equal(nl(dg(Diagram(list(list(f, "unique"), list(g, list())), list(list(g * f, "unique"))), "xy")), "\\xymatrix{\\nA \\ar[d]_{g\\circ f} \\ar[r]^{f} & B \\ar[ld]^{g} \\\\\\nC & \\n}\\n")
  expect_equal(nl(dg(Diagram(list(list(f, "unique"), list(g, list())), list(list(g * f, "unique"))), "xyseq")), "\\xymatrix{\\nA \\ar[r]^{f} \\ar@/_3mm/[rr]_{g\\circ f} & B \\ar[r]^{g} & C \\n}\\n")
  expect_equal(nl({ v <- DiagramGrid(Diagram(list(f, g, h, i)), groups = list(FiniteSet(A, B), FiniteSet(C, D), E)); if (is.character(v)) v else format(v) }), "[[Object(\"E\"), Object(\"C\"), Object(\"D\")], [None, Object(\"A\"), Object(\"B\")]]")
  expect_equal(nl({ v <- DiagramGrid(Diagram(list(f, g, h, i)), groups = list(list(A, B, C), D, E)); if (is.character(v)) v else format(v) }), "[[Object(\"D\"), None, Object(\"E\")], [Object(\"A\"), Object(\"B\"), None], [None, Object(\"C\"), None]]")
  expect_equal(nl({ v <- DiagramGrid(Diagram(list(f, g, h, i)), groups = list(FiniteSet(A, B, C), FiniteSet(D, E))); if (is.character(v)) v else format(v) }), "[[Object(\"D\"), Object(\"E\"), Object(\"A\"), Object(\"B\")], [None, None, None, Object(\"C\")]]")
  expect_equal(nl({ v <- DiagramGrid(Diagram(list(p1, p2, p3, p4, p5, p6, p7, p8, p9, p10, p11, p12)), groups = list(FiniteSet(A, B, C, D), FiniteSet(E, F, G, H))); if (is.character(v)) v else format(v) }), "[[Object(\"A\"), Object(\"B\"), Object(\"E\"), Object(\"F\")], [Object(\"C\"), Object(\"D\"), Object(\"G\"), Object(\"H\")]]")
  expect_equal(nl({ v <- DiagramGrid(Diagram(list(f, g, h, i)), groups = list(list(group = FiniteSet(A, B, C), hints = list(layout = "sequential")), list(group = FiniteSet(D, E), hints = list(transpose = TRUE)))); if (is.character(v)) v else format(v) }), "[[Object(\"D\"), Object(\"A\"), Object(\"B\"), Object(\"C\")], [Object(\"E\"), None, None, None]]")
  expect_equal(nl({ v <- xypic_draw_diagram(Diagram(list(f, g, h, i)), groups = list(FiniteSet(A, B), FiniteSet(C, D), E)); if (is.character(v)) v else format(v) }), "\\xymatrix{\\nE & C \\ar[r]^{h} & D \\ar@/^3mm/[ll]^{i} \\\\\\n& A \\ar[r]^{f} & B \\ar[lu]^{g} \\n}\\n")
  expect_equal(nl({ v <- xypic_draw_diagram(Diagram(list(f, g)), masked = list(g)); if (is.character(v)) v else format(v) }), "\\xymatrix{\\nA \\ar[r]^{f} & B \\\\\\n& C \\n}\\n")
  expect_equal(nl({ v <- xypic_draw_diagram(Diagram(list(f, g)), diagram_format = "@+1cm"); if (is.character(v)) v else format(v) }), "\\xymatrix@+1cm{\\nA \\ar[r]^{f} & B \\ar[d]^{g} \\\\\\n& C \\n}\\n")
})
